def diagonal_language(enumeration):
    return lambda n: not enumeration(n)(n)

def verify_diagonal_separation(enumeration, num_checks=100):
    diag = diagonal_language(enumeration)
    for k in range(num_checks):
        assert enumeration(k)(k) != diag(k)
    return True

def extract_dense_chain(hierarchy, start, length):
    chain = []
    for i in range(length):
        target_level = start + i
        candidates = [p for p in hierarchy.problems if p.level == target_level]
        if not candidates:
            break
        chain.append(candidates[0])
    return chain

def test_completeness_conjecture(hierarchy, max_level):
    results = {}
    for level in range(max_level + 1):
        level_problems = [p for p in hierarchy.problems if p.level == level]
        has_complete = any(
            all(hierarchy.reduces(q, p) for q in level_problems)
            for p in level_problems
        )
        results[level] = has_complete
    return results
